import React, { useState } from 'react';
import { User, MapPin, Search, X, FileText, AlertOctagon, Calendar, CreditCard, ChevronRight, Trophy, CheckCircle2, Phone, Fingerprint, Clock, zap, HardDrive, ShieldCheck } from 'lucide-react';

const CitizensTab = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCitizen, setSelectedCitizen] = useState(null);
  const [activeFilter, setActiveFilter] = useState('PROFILE');

  // --- MOCK DATA ENGINE ---
  const citizens = [
    { id: 'CZ-8821', name: 'ARJUN MEHTA', area: 'GANDHI_NAGAR', zone: 'ZONE_A', status: 'ACTIVE', phone: '+91 98XXX XXXXX', joined: '12_JAN_2025' },
    { id: 'CZ-4412', name: 'SARA KHAN', area: 'SILICON_VALLEY', zone: 'ZONE_C', status: 'OVERDUE', phone: '+91 88XXX XXXXX', joined: '05_FEB_2024' },
    { id: 'CZ-9003', name: 'VIKRAM SINGH', area: 'OLD_TOWN', zone: 'ZONE_B', status: 'ACTIVE', phone: '+91 77XXX XXXXX', joined: '22_NOV_2024' },
  ];

  const citizenStats = {
    reports: [
      { id: 'REP-102', type: 'OVERFLOW', date: '20 MAR', status: 'RESOLVED', color: 'bg-emerald-500' },
      { id: 'REP-099', type: 'MISSED_PCK', date: '15 MAR', status: 'PENDING', color: 'bg-amber-500' },
    ],
    penalties: [
      { id: 'PNL-44', reason: 'MIXED_WASTE', amount: '₹500', date: '10 MAR' },
      { id: 'PNL-12', reason: 'LATE_DISPOSAL', amount: '₹200', date: '02 MAR' },
    ],
    schedules: [
      { day: 'MONDAY', time: '08:00 AM', type: 'DRY_WASTE' },
      { day: 'WEDNESDAY', time: '08:00 AM', type: 'WET_WASTE' },
      { day: 'FRIDAY', time: '09:30 AM', type: 'RECYCLABLES' },
    ],
    subscription: {
      plan: 'PREMIUM_ULTRA',
      price: '₹1,200/mo',
      status: 'ACTIVE',
      expiry: 'APR 2026'
    }
  };

  const closeModal = () => {
    setSelectedCitizen(null);
    setActiveFilter('PROFILE');
  };

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter select-none">

      {/* 📋 MAIN DIRECTORY LIST */}
      <div className="flex flex-col md:flex-row gap-4 items-center justify-between bg-[#FFF24D] p-6 rounded-[32px] border-4 border-[#47510B] shadow-[8px_8px_0_0_#47510B]">
        <div className="flex items-center gap-4">
          <Fingerprint size={40} />
          <h1 className="text-3xl leading-none">CITIZEN_REGISTRY</h1>
        </div>
        <div className="relative w-full md:w-96">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 opacity-30" size={20} />
          <input 
            type="text" 
            placeholder="FILTER_RECORDS..." 
            className="w-full bg-white border-4 border-[#47510B] rounded-2xl p-4 pl-12 outline-none"
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      </div>

      <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {citizens.map(c => (
          <div key={c.id} onClick={() => setSelectedCitizen(c)} className="bg-white border-4 border-[#47510B] p-6 rounded-[40px] shadow-[6px_6px_0_0_#47510B] hover:translate-x-1 transition-all cursor-pointer flex justify-between items-center group">
            <div>
              <p className="text-[10px] text-[#47510B]/40">{c.id}</p>
              <h3 className="text-2xl">{c.name}</h3>
              <p className="text-xs opacity-60">{c.area}</p>
            </div>
            <ChevronRight className="group-hover:translate-x-2 transition-transform" />
          </div>
        ))}
      </div>

      {/* 🏗️ ENHANCED DOSSIER MODAL */}
      {selectedCitizen && (
        <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 md:p-10">
          <div className="absolute inset-0 bg-[#0F172A]/95 backdrop-blur-xl animate-in fade-in duration-300" onClick={closeModal} />

          <div className="relative w-full max-w-7xl h-full max-h-[95vh] bg-[#F8FAFC] border-[6px] border-[#1E293B] rounded-[60px] shadow-[30px_30px_0_0_#6366F1] overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">

            {/* HEADER: ELECTRIC INDIGO THEME */}
            <div className="bg-[#6366F1] p-10 text-white flex justify-between items-center relative overflow-hidden shrink-0">
                <div className="absolute top-0 right-0 p-4 opacity-10 rotate-12"><HardDrive size={200}/></div>
                <div className="flex gap-8 items-center relative z-10">
                    <div className="w-24 h-24 bg-white rounded-[32px] flex items-center justify-center text-[#6366F1] shadow-xl">
                        <User size={56} strokeWidth={3} />
                    </div>
                    <div>
                        <div className="flex items-center gap-3 mb-2">
                            <span className="bg-[#4F46E5] px-4 py-1 rounded-full text-xs tracking-widest border border-white/20">CITIZEN_ID: {selectedCitizen.id}</span>
                            <span className="bg-[#FACC15] text-[#1E293B] px-4 py-1 rounded-full text-xs">SCORE: 980</span>
                        </div>
                        <h2 className="text-5xl md:text-7xl leading-none tracking-tightest">{selectedCitizen.name}</h2>
                    </div>
                </div>
                <button onClick={closeModal} className="relative z-10 bg-black/20 hover:bg-white/20 p-5 rounded-3xl transition-all"><X size={40} /></button>
            </div>

            {/* TAB NAV: SLATE THEME */}
            <div className="bg-[#1E293B] p-4 flex gap-4 overflow-x-auto no-scrollbar shrink-0">
              {[
                { id: 'PROFILE', label: 'IDENTITY', icon: <Fingerprint size={18}/>, color: 'hover:bg-indigo-500' },
                { id: 'REPORTS', label: 'LOGS', icon: <FileText size={18}/>, color: 'hover:bg-emerald-500' },
                { id: 'PENALTIES', label: 'FINES', icon: <AlertOctagon size={18}/>, color: 'hover:bg-rose-500' },
                { id: 'SCHEDULES', label: 'OPS_WINDOW', icon: <Clock size={18}/>, color: 'hover:bg-amber-500' },
                { id: 'SUBS', label: 'WALLET', icon: <CreditCard size={18}/>, color: 'hover:bg-sky-500' }
              ].map(f => (
                <button 
                  key={f.id}
                  onClick={() => setActiveFilter(f.id)}
                  className={`flex items-center gap-3 px-8 py-4 rounded-2xl text-xs font-black transition-all border-b-4 ${activeFilter === f.id ? 'bg-white text-[#1E293B] border-[#FACC15]' : 'bg-white/5 text-white/40 border-transparent ' + f.color}`}
                >
                  {f.icon} {f.label}
                </button>
              ))}
            </div>

            {/* CONTENT AREA: FLUID & COMPLETE */}
            <div className="flex-grow p-12 overflow-y-auto custom-scrollbar-indigo bg-indigo-50/30">

              {/* PROFILE VIEW */}
              {activeFilter === 'PROFILE' && (
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 animate-in slide-in-from-bottom-8">
                  <div className="lg:col-span-8 space-y-10">
                    <section>
                      <label className="text-indigo-400 text-xs mb-4 block">PHYSICAL_RESIDENCE_DATA</label>
                      <p className="text-4xl md:text-5xl leading-none text-[#1E293B]">{selectedCitizen.area}</p>
                      <p className="text-xl mt-4 opacity-50">PLOT 442, SECTOR-7, HYDERABAD, IN</p>
                    </section>
                    <div className="grid grid-cols-2 gap-6">
                       <div className="bg-white p-8 rounded-[40px] border-4 border-[#1E293B] shadow-[8px_8px_0_0_#1E293B]">
                          <label className="text-[10px] opacity-40">ENCRYPTION_ID</label>
                          <p className="text-2xl mt-2">{selectedCitizen.code || 'BETA-09'}</p>
                       </div>
                       <div className="bg-white p-8 rounded-[40px] border-4 border-[#1E293B] shadow-[8px_8px_0_0_#1E293B]">
                          <label className="text-[10px] opacity-40">NETWORK_ENTRY</label>
                          <p className="text-2xl mt-2">{selectedCitizen.joined}</p>
                       </div>
                    </div>
                  </div>
                  <div className="lg:col-span-4 bg-[#1E293B] rounded-[50px] p-10 text-white flex flex-col items-center justify-center text-center">
                     <ShieldCheck size={80} className="text-[#FACC15] mb-6" />
                     <h3 className="text-3xl mb-2">STATUS: VERIFIED</h3>
                     <p className="text-xs opacity-40">ZERO SECURITY BREACHES RECORDED</p>
                  </div>
                </div>
              )}

              {/* REPORTS VIEW */}
              {activeFilter === 'REPORTS' && (
                <div className="space-y-6 animate-in slide-in-from-right-8">
                  {citizenStats.reports.map(r => (
                    <div key={r.id} className="bg-white border-4 border-[#1E293B] p-8 rounded-[35px] flex justify-between items-center group hover:bg-emerald-50 transition-colors shadow-[6px_6px_0_0_#1E293B]">
                      <div className="flex items-center gap-6">
                        <div className={`w-3 h-12 rounded-full ${r.color}`} />
                        <div>
                          <h4 className="text-3xl">{r.type}</h4>
                          <p className="text-xs opacity-40">{r.id} // {r.date}</p>
                        </div>
                      </div>
                      <span className="text-xs font-black bg-[#1E293B] text-white px-6 py-2 rounded-full">{r.status}</span>
                    </div>
                  ))}
                </div>
              )}

              {/* PENALTIES VIEW */}
              {activeFilter === 'PENALTIES' && (
                <div className="space-y-6 animate-in slide-in-from-right-8">
                  {citizenStats.penalties.map(p => (
                    <div key={p.id} className="bg-white border-4 border-rose-500 p-8 rounded-[35px] flex justify-between items-center shadow-[6px_6px_0_0_#F43F5E]">
                      <div>
                        <h4 className="text-3xl text-rose-500">{p.reason}</h4>
                        <p className="text-xs opacity-40">{p.id} // {p.date}</p>
                      </div>
                      <p className="text-4xl">{p.amount}</p>
                    </div>
                  ))}
                </div>
              )}

              {/* SCHEDULES VIEW */}
              {activeFilter === 'SCHEDULES' && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-in slide-in-from-right-8">
                  {citizenStats.schedules.map(s => (
                    <div key={s.day} className="bg-white border-4 border-[#1E293B] p-8 rounded-[40px] text-center shadow-[6px_6px_0_0_#1E293B]">
                      <Calendar size={32} className="mx-auto mb-4 opacity-20" />
                      <p className="text-xl text-[#6366F1]">{s.day}</p>
                      <p className="text-3xl">{s.time}</p>
                      <p className="text-[10px] mt-4 opacity-40 bg-slate-100 py-1 rounded-full">{s.type}</p>
                    </div>
                  ))}
                </div>
              )}

              {/* SUBSCRIPTION VIEW */}
              {activeFilter === 'SUBS' && (
                <div className="bg-white border-4 border-[#1E293B] p-12 rounded-[60px] flex flex-col md:flex-row justify-between items-center shadow-[10px_10px_0_0_#1E293B]">
                   <div>
                      <h3 className="text-6xl text-[#6366F1]">{citizenStats.subscription.plan}</h3>
                      <p className="text-xl opacity-40 mt-2">NEXT_BILLING: {citizenStats.subscription.expiry}</p>
                   </div>
                   <div className="text-right mt-8 md:mt-0">
                      <p className="text-5xl">{citizenStats.subscription.price}</p>
                      <button className="mt-4 bg-[#1E293B] text-white px-8 py-3 rounded-2xl text-xs hover:bg-[#6366F1] transition-all">MANAGE_BILLING</button>
                   </div>
                </div>
              )}

            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CitizensTab;
